<script setup lang="ts">
import {computed} from 'vue';import type {Workbench} from '../app/useWorkbench';import PathField from '../shared/PathField.vue';import JsonReport from '../shared/JsonReport.vue';
const {w}=defineProps<{w:Workbench}>();const s=w.s;const selectedTask=computed(()=>w.task());const selectedCity=computed(()=>w.city());const functionInfo=computed(()=>s.state.function_info?.find((f:any)=>f.name===s.func));const modeOptions=[{id:'existing',title:'使用已有运行 XML',desc:'直接加载当前构建的配置，保留原参数与路径',badge:'直接使用'},{id:'import',title:'原字节副本导入',desc:'外部 XML 原样新增副本，源文件与内容保持原样',badge:'不改路径'},{id:'adapt',title:'新建与路径适配',desc:'从完整样例新建，或预览已有任务 XML 的路径变化',badge:'先预览'}];
function chooseCity(value:string){if(!w.guard())return;s.city=value;if(selectedCity.value?.kind==='indoor'&&!['plindoor','predindoor','indoorrays'].includes(s.func)&&s.state.functions.includes('predindoor'))s.func='predindoor';}
function chooseEngineering(value:string){if(!w.guard())return;s.engineering=value;s.csv=null;s.csvPath=value;void w.restoreBinding();}
</script>
<template><div class="page-heading"><div><div class="eyebrow">TASK & INPUTS</div><h1>为这次计算选择输入</h1><p>三种配置入口独立处理。运行功能来自当前引擎项目。</p></div></div><div class="mode-options"><button v-for="mode in modeOptions" :key="mode.id" :class="{selected:s.mode===mode.id}" @click="w.switchMode(mode.id)" :disabled="!!s.pending||s.runtime.busy"><div><strong>{{mode.title}}</strong><span>{{mode.badge}}</span></div><p>{{mode.desc}}</p></button></div><section class="card"><div class="card-heading"><span class="card-icon">ƒ</span><div><h2>运行功能与任务标识</h2><p>{{functionInfo?.desc||'功能选项由当前项目的 LiShuttleTypes.h 实际内容提供'}}</p></div></div><div class="identity-fields"><label class="field"><span>功能</span><el-select v-model="s.func" :disabled="s.runtime.busy||!!s.pending||s.xmlDirty||s.csvDirty"><el-option v-for="f in s.state.function_info" :key="f.name" :value="f.name" :label="f.name+' · '+(f.label||f.name)"/></el-select></label><label class="field"><span>任务 ID</span><el-input v-model="s.taskId" placeholder="0—2147483647" :disabled="s.runtime.busy||!!s.pending||s.xmlDirty||s.csvDirty"/></label><label class="field" v-if="s.mode==='adapt'"><span>新运行任务名</span><el-input v-model="s.jobName" placeholder="字母、数字、-、_" :disabled="s.runtime.busy||!!s.pending"/></label><el-button v-if="s.mode==='existing'&&s.job" @click="w.updateExecution" :disabled="!!s.pending||s.runtime.busy||s.xmlDirty||s.csvDirty">应用功能与 ID</el-button></div></section>
<section v-if="s.mode==='existing'" class="card"><div class="card-heading"><span class="card-icon teal">XML</span><div><h2>当前构建的运行 XML</h2><p class="mono">{{s.catalog.directory||'选择项目与构建后读取运行目录'}}</p></div><el-button @click="w.run('刷新运行 XML 列表',()=>w.refreshCatalog())" :disabled="!!s.pending||s.xmlDirty||s.csvDirty">刷新列表</el-button></div><label class="field"><span>选择 XML</span><el-select v-model="s.runtimeSchema" data-testid="runtime-select" filterable placeholder="请选择一份可加载配置" :disabled="!!s.pending||s.runtime.busy||s.xmlDirty||s.csvDirty"><el-option v-for="entry in s.catalog.configs" :key="entry.schema" :value="entry.schema" :label="entry.schema+' · name='+(entry.runtime_name||entry.name||'未识别')+(entry.loadable===false?' · '+entry.reason:'')" :disabled="entry.loadable===false"/></el-select></label><div class="info-box">直接加载不会渲染配置、复制资源或修改 Visual Studio 启动项。输出目录以 XML 根 name 为准，加载后必须重新进行运行前检查。</div><div class="button-row"><el-button type="primary" data-testid="runtime-activate" @click="w.activateXml" :disabled="!s.runtimeSchema||!!s.pending||s.runtime.busy">加载实际内容</el-button><el-tag v-if="s.job?.mode==='existing'" type="success">已加载 {{s.job.schema}}</el-tag></div><JsonReport v-if="s.runtimeSchema" :data="s.catalog.configs?.find((x:any)=>x.schema===s.runtimeSchema)" title="查看 XML 内容版本、输入与检测说明"/></section>
<section v-else-if="s.mode==='import'" class="card"><div class="card-heading"><span class="card-icon teal">XML</span><div><h2>原字节副本导入</h2><p>只导入 XML，不同时改写根任务名、输出目录或资源路径</p></div></div><label class="field"><span>从已发现任务中选择 XML（可选）</span><el-select v-model="s.importSource" filterable clearable placeholder="使用任务 XML 候选或下方选择本机文件"><el-option v-for="entry in s.state.tasks.flatMap((t:any)=>(t.schema_candidates||[]))" :key="entry.path" :value="entry.path" :label="entry.path"/></el-select></label><PathField v-model="s.importSource" label="源 XML 文件" kind="file" :extensions="['xml']" :disabled="!!s.pending||s.runtime.busy"/><label class="field"><span>目标文件名（含 .xml）</span><el-input v-model="s.importName" placeholder="例如 project-pred.xml" :disabled="!!s.pending||s.runtime.busy"/></label><div class="button-row"><el-button @click="w.previewImport" :disabled="!s.importSource||!s.importName||!!s.pending">预览导入</el-button><el-button type="primary" @click="w.importXml" :disabled="!w.canImport()||!!s.pending||s.runtime.busy">确认原字节导入</el-button></div><template v-if="w.importPreview.record"><el-alert :type="w.importPreview.record.report?.conflict?'error':'info'" :title="w.importPreview.record.report?.conflict?'目标 XML 或同名装配记录已存在，请改名或直接使用当前文件。':'请核对源与目标。相对路径将按当前程序 Bin 目录解释。'" :closable="false" show-icon/><el-button v-if="w.importPreview.record.report?.conflict&&s.catalog.configs?.some((x:any)=>x.schema===s.importName)" @click="s.runtimeSchema=s.importName;w.activateXml()" class="spaced-alert">直接使用当前同名文件</el-button><JsonReport :data="w.importPreview.record.report" title="查看导入预览与实际输出目录"/></template></section>
<template v-else><div class="grid-two"><section class="card"><div class="card-heading"><span class="card-icon teal">M</span><div><h2>地图与场景</h2><p>依据实际内容区分室内 .das 与室外地图</p></div><el-button size="small" @click="w.rescan('map')" :disabled="!!s.pending||s.runtime.busy">重新扫描</el-button></div><PathField v-model="s.draft.MAP_ROOT" label="地图根目录" :disabled="!!s.pending||s.runtime.busy"/><el-select :model-value="s.city" filterable placeholder="选择地图或室内场景" @change="chooseCity" :disabled="!!s.pending||s.runtime.busy"><el-option v-for="c in s.state.cities" :key="c.name" :value="c.name" :label="c.name+' · '+(c.kind==='indoor'?'室内':'室外')"/></el-select><div v-if="selectedCity" class="check-list"><div v-for="check in selectedCity.checks" :key="check[0]" :class="{bad:!check[2]}"><b>{{check[2]?'✓':'!'}}</b><span>{{check[0]}}</span><code>{{check[1]}}</code></div></div><el-empty v-else description="选择一张地图，核对内容完整性" :image-size="65"/></section><section class="card"><div class="card-heading"><span class="card-icon lilac">T</span><div><h2>工参任务</h2><p>CSV 与任务配置有多个候选时，需要明确选择</p></div><el-button size="small" @click="w.rescan('gongcan')" :disabled="!!s.pending||s.runtime.busy">重新扫描</el-button></div><PathField v-model="s.draft.GONGCAN_ROOT" label="工参任务根目录" :disabled="!!s.pending||s.runtime.busy"/><label class="field"><span>任务</span><el-select :model-value="s.taskDir" filterable placeholder="选择工参任务" @change="w.selectTask" :disabled="!!s.pending||s.runtime.busy"><el-option v-for="t in s.state.tasks" :key="t.dir" :value="t.dir" :label="t.name+' · '+(t.kind==='indoor'?'室内':t.kind==='outdoor'?'室外':'待确认')"/></el-select></label><label class="field"><span>工参 CSV</span><el-select :model-value="s.engineering" placeholder="明确选择工参文件" @change="chooseEngineering" :disabled="!selectedTask||!!s.pending||s.runtime.busy"><el-option v-for="p in selectedTask?.engineering_candidates||[]" :key="p" :value="p" :label="p"/></el-select><small>{{selectedTask?.engineering_reason}}</small></label><JsonReport v-if="selectedTask" :data="selectedTask" title="查看工参格式、任务资源与候选文件"/></section></div><section class="card"><div class="card-heading"><span class="card-icon">↔</span><div><h2>配置来源与路径适配</h2><p>完整样例新建，或基于任务 XML 预览来源到目标变化</p></div></div><label class="field"><span>XML 来源</span><el-select v-model="s.source" clearable placeholder="使用完整项目样例新建" :disabled="!!s.pending||s.runtime.busy"><el-option value="" label="完整项目样例 · 新建配置"/><el-option v-for="entry in selectedTask?.schema_candidates||[]" :key="entry.path" :value="entry.path" :label="entry.path+' · name='+entry.name"/></el-select></label><div class="option-row"><el-checkbox v-model="s.syncEngineering" v-if="s.source" :disabled="!!s.pending||s.runtime.busy">将所选工参同步到适配副本</el-checkbox><el-checkbox v-model="s.copyModels" v-if="!s.source" :disabled="!!s.pending||s.runtime.busy">装配任务模型资源</el-checkbox><el-checkbox v-model="s.copyAntennas" :disabled="!selectedTask?.has_antennas||!!s.pending||s.runtime.busy">独立装配任务天线资源</el-checkbox></div><label class="field"><span>区域文件</span><el-select v-model="s.polygon" clearable placeholder="不使用区域（PolygonFilePath 为空）" :disabled="!!s.pending||s.runtime.busy"><el-option value="" label="不使用区域"/><el-option v-for="p in selectedTask?.txts||[]" :key="p" :value="p" :label="p"/></el-select></label><div v-if="s.source" class="subsection"><div class="section-line"><h3>本机路径覆盖</h3><el-button size="small" @click="w.refreshLocalPaths" :disabled="!!s.pending||s.runtime.busy">识别默认路径</el-button></div><div class="form-grid"><PathField v-for="(value,key) in {...s.pathDefaults,...s.pathOverrides}" :key="key" :model-value="s.pathOverrides[key]??value" @update:model-value="s.pathOverrides[key]=$event" :label="String(key)" :hint="s.localIssues[key]||'仅填写明确需要改变的本机路径'" :disabled="!!s.pending||s.runtime.busy"/></div></div><div class="button-row"><el-button @click="w.saveBinding" :disabled="!s.engineering||!s.city||!!s.pending||s.runtime.busy">保存任务与地图对应关系</el-button><el-button @click="w.restoreBinding" :disabled="!selectedTask||!!s.pending||s.runtime.busy">恢复对应关系</el-button></div></section></template></template>
